<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';
import { FitnessSettingsDraftSchema,SiteSettingsSchema,fitnessDayCount,type FitnessSettingsDraft,type SiteSettings } from '@xvyin/contracts';
import { api,errorMessage,type DraftRecord } from '../api';
import type { ReleaseChange } from './ReleasePanel.vue';import RichTextEditor from './RichTextEditor.vue';import AssetField from './AssetField.vue';import PlatformSyncPanel from './PlatformSyncPanel.vue';
const props=defineProps<{kind:'site'|'fitness'}>();const emit=defineEmits<{publish:[changes:ReleaseChange[]];passwordChanged:[];dirty:[value:boolean]}>();
const record=ref<DraftRecord<SiteSettings|FitnessSettingsDraft>|null>(null);const local=ref<SiteSettings|FitnessSettingsDraft|null>(null);const loading=ref(true);const busy=ref(false);const issue=ref('');const saved=ref(false);const currentPassword=ref('');const newPassword=ref('');const confirmation=ref('');const passwordIssue=ref('');
const site=computed(()=>local.value as SiteSettings);const fitness=computed(()=>local.value as FitnessSettingsDraft);const days=computed(()=>{try{return fitnessDayCount(fitness.value?.startDate??null,new Date());}catch{return null;}});
async function load(){loading.value=true;issue.value='';try{const response=await api.request<DraftRecord<SiteSettings|FitnessSettingsDraft>>(`/admin/settings/${props.kind}`);record.value=response.data;local.value=JSON.parse(JSON.stringify(response.data.draft));saved.value=false;emit('dirty',false);}catch(error){issue.value=errorMessage(error);}finally{loading.value=false;}}
async function save(publish=false){if(!record.value||!local.value)return;busy.value=true;issue.value='';saved.value=false;try{const draft=(props.kind==='site'?SiteSettingsSchema:FitnessSettingsDraftSchema).parse(local.value);if(props.kind==='fitness')fitnessDayCount((draft as FitnessSettingsDraft).startDate,new Date());const response=await api.request<DraftRecord<SiteSettings|FitnessSettingsDraft>>(`/admin/settings/${props.kind}`,{method:'PATCH',body:{draft,expectedVersion:record.value.version}});record.value=response.data;local.value=JSON.parse(JSON.stringify(response.data.draft));saved.value=true;emit('dirty',false);if(publish)emit('publish',[{collection:'settings',id:props.kind,version:response.data.version,action:'publish'}]);}catch(error){issue.value=errorMessage(error);}finally{busy.value=false;}}
function newId(){return crypto.randomUUID();}
function confirmDiscard(message:string){return window.confirm(message);}
function moveNavigation(index:number,direction:number){const to=index+direction;if(to<0||to>=site.value.navigation.length)return;const item=site.value.navigation.splice(index,1)[0];if(item)site.value.navigation.splice(to,0,item);site.value.navigation.forEach((nav,i)=>nav.sortOrder=i);emit('dirty',true);}
async function changePassword(){passwordIssue.value='';if(newPassword.value!==confirmation.value){passwordIssue.value='两次新密码不一致。';return;}busy.value=true;try{await api.request('/auth/password',{method:'POST',body:{currentPassword:currentPassword.value,newPassword:newPassword.value}});currentPassword.value='';newPassword.value='';confirmation.value='';emit('passwordChanged');}catch(error){passwordIssue.value=errorMessage(error);}finally{busy.value=false;}}
onMounted(load);
</script>
<template><div><p v-if="loading" class="loading" role="status">正在读取设置…</p><div v-if="issue" class="notice error" role="alert">{{issue}}<button v-if="!local" class="text-button" @click="load">重新读取</button></div><form v-if="local" @submit.prevent="save(false)" @input="saved=false;emit('dirty',true)"><fieldset class="editor-fieldset" :disabled="busy"><template v-if="kind==='fitness'"><div class="fitness-settings panel"><div><p class="eyebrow">FITNESS · ASIA / SHANGHAI</p><h2>从真实的第一天开始</h2><p class="hint mt16">日历天数从开始当天算第 1 天，与训练时长、打卡次数无关。</p><div class="fitness-day mt24"><strong v-if="days!==null">{{days}}</strong><strong v-else class="unset">待设置</strong><span>{{days!==null?'个日历日':'开始日期为空，前台不显示天数'}}</span></div></div><div><label class="field">真实开始日期<input :value="fitness.startDate??''" type="date" @input="fitness.startDate=($event.target as HTMLInputElement).value||null"><small class="hint">日期未提供时保留空值；不可使用未来日期。</small></label><label class="field mt16">健身页介绍<textarea v-model="fitness.intro" maxlength="2000" rows="4"></textarea></label><label class="check"><input v-model="fitness.enabled" type="checkbox">显示健身板块</label></div></div></template><template v-else><div class="settings-grid"><section class="panel"><h2>网站与个人介绍</h2><label class="field mt24">网站名称<input v-model="site.siteTitle" maxlength="80" required></label><label class="field">首页招呼<input :value="site.heroTitle" readonly><small class="hint">沿用已确定的原文与书法姓名。</small></label><label class="field">首页简介<textarea v-model="site.intro" rows="5" maxlength="2000"></textarea></label><AssetField v-model="site.avatarAssetId" label="头像素材" kind="image" optional/><p class="hint mt8">留空时沿用原头像。</p><label class="field mt24">外观偏好<select v-model="site.themePreference"><option value="system">跟随系统</option><option value="light">纸白</option><option value="dark">墨色</option></select></label><label class="field">页脚文字<textarea v-model="site.footerText" rows="3" maxlength="500"></textarea></label></section><section class="panel"><h2>导航与联系</h2><div v-for="(nav,index) in site.navigation" :key="nav.href" class="nav-editor-row"><label class="check"><input v-model="nav.enabled" type="checkbox"><span class="sr-only">显示 {{nav.label}}</span></label><label class="field"><span class="sr-only">导航名称</span><input v-model="nav.label" maxlength="20"><small class="mono">{{nav.href}}</small></label><button type="button" :disabled="index===0" aria-label="导航前移" @click="moveNavigation(index,-1)">↑</button><button type="button" :disabled="index===site.navigation.length-1" aria-label="导航后移" @click="moveNavigation(index,1)">↓</button></div><label class="check mt24"><input v-model="site.contactEnabled" type="checkbox">开启访客联系表单</label><div class="flex between mt32"><h3>社交链接</h3><button type="button" :disabled="site.socialLinks.length>=20" @click="site.socialLinks.push({id:newId(),label:'',url:''});emit('dirty',true)">添加</button></div><div v-if="!site.socialLinks.length" class="empty mt16">未设置社交链接。</div><div v-for="(social,index) in site.socialLinks" :key="social.id" class="social-edit mt16"><label class="field">名称<input v-model="social.label" maxlength="40" required></label><label class="field">HTTPS 地址<input v-model="social.url" type="url" required placeholder="https://"></label><button type="button" class="danger" @click="site.socialLinks.splice(index,1);emit('dirty',true)">移除</button></div></section></div><section class="panel mt24"><h2 class="mb24">关于我</h2><RichTextEditor v-model="site.about" label="关于我的正文" @update:model-value="emit('dirty',true)"/></section></template><div class="flex between mt24"><span class="hint" role="status">{{saved?'草稿已保存，发布后才会更新前台。':`当前保存版本 ${record?.version??0}`}}</span><div class="flex"><button type="button" :disabled="busy" @click="confirmDiscard('重新读取会放弃未保存的设置，继续吗？')&&load()">重新读取</button><button type="submit">保存草稿</button><button type="button" class="primary" @click="save(true)">保存并准备发布</button></div></div></fieldset></form><PlatformSyncPanel v-if="kind==='site'"/><section v-if="kind==='site'" class="panel account-settings mt40"><h2>管理员密码</h2><p class="hint mt16">修改后当前和其他设备的管理员会话都会撤销，需要重新登录。</p><form class="form-grid mt24" @submit.prevent="changePassword"><label class="field">当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" required maxlength="1024"></label><label class="field">新密码<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="15" maxlength="128"><small class="hint">15–128 个字符，建议使用密码管理器生成。</small></label><label class="field">再次输入新密码<input v-model="confirmation" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label><div class="field"><span class="sr-only">确认修改</span><button :disabled="busy" type="submit">修改密码并退出所有会话</button></div><p v-if="passwordIssue" class="notice error span2" role="alert">{{passwordIssue}}</p></form></section></div></template>
